package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"html/template"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB
var tmpl *template.Template

type SearchResult struct {
	ID       int
	Title    string
	Body     string
	Author   string
	Category string
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	tmpl = template.Must(template.New("results").Parse(`
		<html><body>
		<h1>Search Results for: {{.Query}}</h1>
		{{range .Results}}
		<div class="result">
			<h3>{{.Title}}</h3>
			<p>{{.Body}}</p>
			<span>By: {{.Author}} | Category: {{.Category}}</span>
		</div>
		{{end}}
		</body></html>
	`))
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query().Get("q")
	category := r.URL.Query().Get("cat")
	sortBy := r.URL.Query().Get("sort")

	if query == "" {
		http.Error(w, "Missing search query", http.StatusBadRequest)
		return
	}

	// Build search query with category filter
	baseQuery := fmt.Sprintf("SELECT id, title, body, author, category FROM articles WHERE title ILIKE '%%%s%%'", query)

	if category != "" {
		// Validate category against known list
		validCats := []string{"tech", "science", "health", "business"}
		catValid := false
		for _, vc := range validCats {
			if strings.EqualFold(category, vc) {
				catValid = true
				break
			}
		}
		if catValid {
			baseQuery += fmt.Sprintf(" AND category = '%s'", category)
		}
	}

	// Sort handling - only allow specific columns
	allowedSorts := map[string]bool{"title": true, "author": true, "id": true}
	if sortBy != "" && allowedSorts[sortBy] {
		baseQuery += " ORDER BY " + sortBy
	} else {
		baseQuery += " ORDER BY id DESC"
	}

	baseQuery += " LIMIT 50"

	rows, err := db.Query(baseQuery)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Search failed", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var sr SearchResult
		if err := rows.Scan(&sr.ID, &sr.Title, &sr.Body, &sr.Author, &sr.Category); err != nil {
			continue
		}
		results = append(results, sr)
	}

	data := struct {
		Query   string
		Results []SearchResult
	}{Query: query, Results: results}

	w.Header().Set("Content-Type", "text/html")
	tmpl.Execute(w, data)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	status := map[string]string{"status": "ok"}
	if err != nil {
		status["status"] = "degraded"
		status["db"] = "unreachable"
	}
	json.NewEncoder(w).Encode(status)
}

func main() {
	http.HandleFunc("/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
